} else if (topic === "almikatro/yahi/percent_soil_citern" && texte !== "") {
    try {
        let data = JSON.parse(texte);
        if (data.Soil !== undefined) etat.soil = data.Soil;
        if (data.citerne !== undefined) etat.citerne = data.citerne;
    } catch (e) {}
}

// 3. Mise à jour des équipements via le topic cmd
else if (topic === "almikatro/yahi/cmd") {
    if (texte === "Pompe_on") etat.pompe_p = "ON";
    if (texte === "Pompe_off") etat.pompe_p = "OFF";
    if (texte === "Pompe_off_citerne_vide") { etat.pompe_p = "OFF (Citerne vide)"; etat.pompe_s = "OFF"; }
    if (texte === "ALARME_POMPE_TIMEOUT") etat.pompe_s = "ON";
    if (texte === "Pas_d'alarme_Pompe") etat.pompe_s = "OFF";

    if (texte === "Ventilo_on") etat.ventilo_p = "ON";
    if (texte === "Ventilo_off") etat.ventilo_p = "OFF";
    if (texte === "ALARME_VENTILO_TIMEOUT") etat.ventilo_s = "ON";
    if (texte === "Pas_d'alarme_Ventilo") etat.ventilo_s = "OFF";

    if (texte === "dehumidifier_on") etat.dehum_p = "ON";
    if (texte === "dehumidifier_off") etat.dehum_p = "OFF";
    if (texte === "ALARME_DEHUMIDIFIER_TIMEOUT") etat.dehum_s = "ON";
    if (texte === "Pas_d'alarme_Dehumidificateur") etat.dehum_s = "OFF";

    if (texte === "chauffage_on") etat.chauffage_p = "ON";
    if (texte === "chauffage_off") etat.chauffage_p = "OFF";
    if (texte === "ALARME_CHAUFFAGE_TIMEOUT") etat.chauffage_s = "ON";
    if (texte === "Pas_d'alarme_Chauffage") etat.chauffage_s = "OFF";
}

global.set("etat_station", etat);
return null;

let chatId = msg.payload.chatId;
if (chatId !== 6837941372) {
    return null;
}

let texte = String(msg.payload.content || "").trim().toLowerCase();

if (texte === "info") {
    let e = global.get("etat_station") || {};

    let bilan = "📊 ÉTAT ACTUEL - STATION AIN NAADJA\n" +
                "Statut : " + (e.statut ?? "🔴 HORS LIGNE") + "\n\n" +
                "🌡️ Température : " + (e.temp ?? "--") + " °C\n" +
                "💧 Humidité Air : " + (e.humidity ?? "--") + " %\n" +
                "🌱 Humidité Sol : " + (e.soil ?? "--") + " %\n" +
                "🛢️ Citerne : " + (e.citerne ?? "--") + " %\n\n" +
                "⚙️ ÉQUIPEMENTS :\n" +
                "• Pompes : Princ. [" + (e.pompe_p ?? "??") + "] | Sup. [" + (e.pompe_s ?? "??") + "]\n" +
                "• Ventilateurs : Princ. [" + (e.ventilo_p ?? "??") + "] | Sup. [" + (e.ventilo_s ?? "??") + "]\n" +
                "• Déshumidif. : Princ. [" + (e.dehum_p ?? "??") + "] | Sup. [" + (e.dehum_s ?? "??") + "]\n" +
                "• Chauffages : Princ. [" + (e.chauffage_p ?? "??") + "] | Sup. [" + (e.chauffage_s ?? "??") + "]";

    msg.payload = {
        chatId: chatId,
        type: "message",
        content: bilan
    };
    return msg;
}

return null;

// Récupération des 4 dictionnaires d'historique en mémoire globale
let donneesSauvegarde = {
    ventilo: global.get("Ventilo_historique") || {},
    pompe: global.get("Pompe_historique") || {},
    chauffage: global.get("chauffage_historique") || {},
    dehumidificateur: global.get("Dehumidificateur_historique") || {}
};

// On convertit l'ensemble en texte JSON pour le stocker proprement dans un champ InfluxDB
msg.payload = {
    backup_json: JSON.stringify(donneesSauvegarde)
};

return msg;

let resultats = msg.payload;

if (Array.isArray(resultats) && resultats.length > 0 && resultats[0]._value) {
    try {
        let sauvegarde = JSON.parse(resultats[0]._value);

        if (sauvegarde.ventilo) global.set("Ventilo_historique", sauvegarde.ventilo);
        if (sauvegarde.pompe) global.set("Pompe_historique", sauvegarde.pompe);
        if (sauvegarde.chauffage) global.set("chauffage_historique", sauvegarde.chauffage);
        if (sauvegarde.dehumidificateur) global.set("Dehumidificateur_historique", sauvegarde.dehumidificateur);

        node.status({fill: "green", shape: "dot", text: "Historiques 30j restaurés"});
    } catch (e) {
        node.error("Erreur lecture sauvegarde InfluxDB : " + e.message);
    }
} else {
    node.status({fill: "yellow", shape: "ring", text: "Aucune sauvegarde trouvée"});
}

return null;
